package org.zhixiaoce.aperture;
import java.util.*;import java.util.concurrent.atomic.*;import java.net.*;import com.sun.net.httpserver.*;import okhttp3.*;
public class CinemaStreamTest {
 static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}interface Work{void run()throws Exception;}static void reject(Work w,String s)throws Exception{try{w.run();}catch(Exception expected){checks++;return;}throw new AssertionError(s);}
 public static void main(String[] args)throws Exception{
  for(int heap:new int[]{64,128,192,256,512,1024})for(boolean live:new boolean[]{true,false}){CinemaStreamPolicy p=new CinemaStreamPolicy(live,heap);check(p.minBufferMs>=p.rebufferMs&&p.maxBufferMs>=p.minBufferMs&&p.startMs<=p.minBufferMs,"consistent playback buffer thresholds");check(p.targetBytes<=48*1024*1024&&p.targetBytes>=8*1024*1024,"heap-adaptive memory target bounded");if(live)check(p.maxBufferMs<30000,"live uses lower-latency buffer profile");}
  check(CinemaStreamPolicy.diskBudget(32L*1024*1024)==0,"low storage bypasses VOD disk cache");check(CinemaStreamPolicy.diskBudget(4L*1024*1024*1024)==128L*1024*1024,"VOD disk cache maximum 128MiB");check(CinemaStreamPolicy.diskBudget(128L*1024*1024)<=16L*1024*1024,"small free space scales cache down");
  Map<String,String> a=new LinkedHashMap<>();a.put("Authorization","fixture-a");a.put("User-Agent","fixture");Map<String,String> b=new LinkedHashMap<>();b.put("user-agent","fixture");b.put("authorization","fixture-a");b.put("Range","bytes=4096-");String key=CinemaStreamPolicy.cacheKey("https://example.invalid/v",a);check(key.equals(CinemaStreamPolicy.cacheKey("https://example.invalid/v",b)),"header order/case and byte-range do not split the same cached resource");b.put("authorization","fixture-b");check(!key.equals(CinemaStreamPolicy.cacheKey("https://example.invalid/v",b)),"different credentials never share media bytes");check(!key.equals(CinemaStreamPolicy.cacheKey("https://example.invalid/other",a)),"different URL never shares media bytes");check(key.matches("[a-f0-9]{64}")&&!key.contains("fixture"),"cache index key is hashed");check(CinemaStreamPolicy.nativeFallback(4001)&&CinemaStreamPolicy.nativeFallback(3003)&&!CinemaStreamPolicy.nativeFallback(2002),"codec/format fallback does not treat network errors as decoder errors");
  HttpServer origin=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0),other=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);AtomicReference<String> same=new AtomicReference<>(),cross=new AtomicReference<>();AtomicInteger calls=new AtomicInteger();byte[] media=new byte[8192];for(int i=0;i<media.length;i++)media[i]=(byte)(i%251);String base="http://127.0.0.1:"+origin.getAddress().getPort();
  origin.createContext("/same",e->{same.set(e.getRequestHeaders().getFirst("Authorization"));e.sendResponseHeaders(200,1);e.getResponseBody().write(1);e.close();});origin.createContext("/redirect",e->{e.getResponseHeaders().set("Location","/same");e.sendResponseHeaders(302,-1);e.close();});
  other.createContext("/other",e->{cross.set(e.getRequestHeaders().getFirst("Authorization")+"|"+e.getRequestHeaders().getFirst("Cookie")+"|"+e.getRequestHeaders().getFirst("X-Private")+"|"+e.getRequestHeaders().getFirst("Range"));e.sendResponseHeaders(200,1);e.getResponseBody().write(1);e.close();});origin.createContext("/cross",e->{e.getResponseHeaders().set("Location","http://localhost:"+other.getAddress().getPort()+"/other");e.sendResponseHeaders(302,-1);e.close();});
  origin.createContext("/range",e->{calls.incrementAndGet();int at=e.getRequestHeaders().getFirst("Range").contains("4096")?4096:0;e.getResponseHeaders().set("Content-Range","bytes "+at+"-8191/8192");e.sendResponseHeaders(206,8192-at);e.getResponseBody().write(media,at,8192-at);e.close();});
  origin.createContext("/hls",e->{byte[] data="#EXTM3U\n#EXT-X-TARGETDURATION:6\n#EXTINF:6,\npart.ts\n".getBytes();e.getResponseHeaders().set("Content-Type","application/vnd.apple.mpegurl");e.sendResponseHeaders(200,data.length);e.getResponseBody().write(data);e.close();});origin.start();other.start();
  OkHttpClient client=CinemaStreamHttp.client(base,true);try{
   try(Response r=client.newCall(new Request.Builder().url(base+"/redirect").header("Authorization","fixture").build()).execute()){check(r.isSuccessful()&&"fixture".equals(same.get()),"same-origin redirect retains explicit source credentials");}
   try(Response r=client.newCall(new Request.Builder().url(base+"/cross").header("Authorization","fixture").header("Cookie","fixture=1").header("X-Private","fixture").header("Range","bytes=4096-").build()).execute()){check(r.isSuccessful()&&"null|null|null|bytes=4096-".equals(cross.get()),"cross-origin segment/redirect strips private headers and keeps byte range");}
   try(Response r=client.newCall(new Request.Builder().url(base+"/range").header("Range","bytes=4096-").build()).execute()){check(r.code()==206&&Arrays.equals(r.body().bytes(),Arrays.copyOfRange(media,4096,8192)),"partial media range returns correct resumed bytes");}
   OkHttpClient blocked=CinemaStreamHttp.client(base,false);try{reject(()->{try(Response r=blocked.newCall(new Request.Builder().url(base+"/range").header("Range","bytes=4096-").build()).execute()){}},"HTTP segment rejected when user policy disallows HTTP");}finally{blocked.connectionPool().evictAll();}check(calls.get()==1,"disallowed HTTP request sends no media request headers");
   CinemaCatalog.Episode prepared=new CinemaHttp().media(new CinemaCatalog.Episode("HLS",base+"/hls"),true);check(prepared.mime.equals("application/x-mpegURL"),"HLS sniff supplies media type even without a filename extension");
  }finally{client.connectionPool().evictAll();origin.stop(0);other.stop(0);}
  System.out.println(checks+" production streaming budget/cache-key and local HTTP/range assertions passed");
 }
}
